package com.shopsphere;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.oauth2.jwt.Jwt;
class AuthServiceTest {UserRepository.InMemory repo;JwtService jwt;AuthService service;@BeforeEach void setup(){repo=new UserRepository.InMemory();jwt=new JwtService("test-secret-that-is-definitely-long-enough",15,7);service=new AuthService(repo,new BCryptPasswordEncoder(4),jwt);}@Test void registrationHashesPasswordAndRejectsDuplicates(){var request=new AuthDtos.RegisterRequest("Aarav","Mehta","AARAV@example.com","Secret123","+91 9876543210");var created=service.register(request);assertEquals("aarav@example.com",created.email());assertTrue(repo.findByEmail(created.email()).orElseThrow().passwordHash().startsWith("$2"));assertThrows(ConflictException.class,()->service.register(request));}@Test void loginAndJwtValidation(){service.register(new AuthDtos.RegisterRequest("A","M","a@example.com","Secret123",null));var tokens=service.login(new AuthDtos.LoginRequest("a@example.com","Secret123"));Jwt parsed=jwt.validate(tokens.accessToken(),"access");assertEquals("a@example.com",parsed.getClaimAsString("email"));assertThrows(UnauthorizedException.class,()->service.login(new AuthDtos.LoginRequest("a@example.com","wrong")));}}
